package ma.autocarnet.radouane;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.file.*;
public class PersonalStoreTest {public static void main(String[] args)throws Exception{File root=Files.createTempDirectory(Path.of("build"),"personal-store-").toFile();Context a=new Context(new File(root,"first")),b=new Context(new File(root,"restore"));String json;try(InputStream in=new FileInputStream("build/personal-radouane/assets/private-seed.zip")){json=Store.importFile(a,in);}Store.save(a,json);JSONObject d=new JSONObject(Store.load(a));if(d.getJSONArray("historicalRecords").length()!=12||d.getJSONObject("vehicle").getInt("baselineKm")!=64084||Store.photoIds(d).size()!=3)throw new AssertionError();for(String id:Store.photoIds(d))if(!Store.photo(a,id).isFile())throw new AssertionError();ByteArrayOutputStream bytes=new ByteArrayOutputStream();Store.exportZip(a,json,bytes);String restored=Store.importFile(b,new ByteArrayInputStream(bytes.toByteArray()));Store.save(b,restored);if(!restored.equals(json))throw new AssertionError("Archive data lost");for(String id:Store.photoIds(d))if(!java.util.Arrays.equals(Files.readAllBytes(Store.photo(a,id).toPath()),Files.readAllBytes(Store.photo(b,id).toPath())))throw new AssertionError("Photo changed");System.out.println("Personal seed and backup verified: all 12 previous-owner records and 3 identical photos preserved.");}}
